import{_ as i,l,o as a,c as r,v as o,p as d,x as t,d as p,i as c,S as s}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"空与 Option","description":"","frontmatter":{"title":"空与 Option","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/null-option.md","filePath":"cs/null-option.md","lastUpdated":1789023840000}'),u={name:"cs/null-option.md"};function h(_,e,m,f,E,A){const n=l("Mermaid");return a(),r("div",null,[e[1]||(e[1]=o('<h1 id="空与-option" tabindex="-1">空与 Option <a class="header-anchor" href="#空与-option" aria-label="Permalink to &quot;空与 Option&quot;">​</a></h1><div class="epigraph"><p>`null` 是每个引用类型上的隐式和。Option/Maybe 把空变成显式构造子，穷尽检查才能过关；分析器只能近似谁为空。</p><footer>—— 据 Hoare 对空引用的反思；Pierce TAPL 的和类型；Maranget 穷尽性对照整理</footer></div><p>上一课<a href="/cs/abstract-interpretation">抽象解释</a>可把「可能空」当成抽象值。缺口是语言设计：<strong>空该不该进每一个指针类型</strong>。Hoare 称空引用是十亿元错误。本课用<a href="/cs/adt-pattern-compile">ADT</a> 的 <code>None | Some t</code> 对照 C/<code>null</code>、Java 的 NPE、Option。类型单元在此收束，下一单元中端优化假定 IR 上的值已经没有隐式空，或空被显式测试。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若 <code>T</code> 的值含 <code>null</code>，则每一解引用都可能卡住或抛例外。进展定理要把 NPE 当合法一步，于是「井型」不再表示「能读字段」。Option：类型是 \\(1+\\tau\\)，匹配强迫处理。缺口是<strong>把空从默认别名里拿出来</strong>，不是再定义 Galois。</p><p>可空注解（<code>@Nullable</code>）是渐进/契约，运行时仍可能破。抽象解释找 NPE 是事后；Option 是事前。</p><h3 id="undefined-不是-null" tabindex="-1"><code>undefined</code> 不是 <code>null</code> <a class="header-anchor" href="#undefined-不是-null" aria-label="Permalink to &quot;`undefined` 不是 `null`&quot;">​</a></h3><p>JavaScript 的双底是另一设计事故。C 的未初始化是 UB，更不是 Option。不要三者混名。</p><p><span class="marginnote">Hoare, Null References: The Billion Dollar Mistake（演讲）。SML <code>option</code>、Haskell <code>Maybe</code>、Rust <code>Option</code>。Pierce 和类型。本课不把 SQL NULL 的三值逻辑写进 PL 规则。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>核心语言加和类型。表面：<code>?.</code> 是对 Option 的语法糖，应降成匹配，而不是再引入隐式空。与<a href="/cs/exhaustiveness-check">穷尽性</a>：漏 <code>None</code> 即警告。与借用：<code>Option&lt;&amp;T&gt;</code> 的寿命仍走区域。</p>',11)),(a(),d(s,null,{default:t(()=>[c(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NULL%5B%22%E9%9A%90%E5%BC%8F%20null%20%E2%88%88%20T%22%5D%20--%3E%20NPE%5B%22%E8%A7%A3%E5%BC%95%E7%94%A8%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20OPT%5B%22Option%20T%20%3D%201%2BT%22%5D%20--%3E%20MATCH%5B%22%E5%8C%B9%E9%85%8D%E7%A9%B7%E5%B0%BD%22%5D%0A%20%20MATCH%20--%3E%20SAFE%5B%22%E6%97%A0%E9%9A%90%E5%BC%8F%E7%A9%BA%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>互操作：FFI 从 C 进来的指针仍可能空，要在边界包成 Option——渐进课的强制在此落地。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>表示：<code>Option&lt;&amp;T&gt;</code> 可用空指针位模式优化（Rust 的 nullable pointer optimization），这是表示 trick，类型仍是和。不要把优化当「其实还是 null」。</p><p>分析：即使有 Option，内部仍可用 AI 证明某 <code>unwrap</code> 安全以消除检查。类型不排斥分析。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写所有可选链的语义。后课默认：空应是显式和类型；中端见到的是测试与 φ。下一课常量传播：在 IR 上把已知值推过去，包括「已知是 Some」。</p><p>也不把空当线性资源；线性管次数，Option 管存在。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>隐式 null 削弱「井型即能解引用」。</li><li>Option 是 \\(1+\\tau\\)，穷尽检查补枝。</li><li>抽象解释可找 NPE；语言设计可取消隐式空。</li><li>出处：Hoare 演讲；Pierce 和类型；对照 Maranget；Cousot 分析。</li></ul>',9))])}const B=i(u,[["render",h]]);export{P as __pageData,B as default};
